#include <stack>
#include <iostream>

int main() {
    std::stack<int> s;
    s.push(42);

    // Correct usage: must check empty()
    if (!s.empty()) {
        int value = s.top(); // Get element
        s.pop();           // Remove element
        std::cout << value << std::endl;
    }

    // DANGER: Undefined Behavior
    // s.pop(); // Called on empty stack

    return 0;
}
